import {createApi,cashfreeCheckout} from './client.mjs';const api=createApi(window.PLANTO_CONFIG?.apiUrl||''),token=location.hash.slice(1),output=document.querySelector('#result');
async function status(){const r=await api.request('/v1/checkout/'+encodeURIComponent(token)+'/status','POST',{});output.textContent=r.paid?'Payment verified. You can return to the mobile app.':'Payment not confirmed yet. Check again before retrying.';}
document.querySelector('#pay').onclick=async e=>{e.target.disabled=true;try{const r=await api.request('/v1/checkout/'+encodeURIComponent(token),'POST',{});await cashfreeCheckout(r);await status();}catch(e){output.textContent=e.message;}finally{e.target.disabled=false;}};document.querySelector('#status').onclick=()=>status().catch(e=>output.textContent=e.message);
